import sys, json
from pathlib import Path
import torch
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "tools"))
import metric

OUT = Path(__file__).parent
d = {int(L): v.float() for L, v in torch.load(OUT / "dc_last.pt", weights_only=False).items()}
baseline = 0.1275

def score(vecs, positions, scale):
    r = metric.run_metric(vecs, positions, scale)
    return r["pass_at_10"], r["mean_log10_rank"]

configs = []
for layers in ([26], [24], [24,26], [26,28], [26,28,30], [22,24,26], [24,26,28], [20,22,24,26]):
    for sc in (0.5, 1.0, 2.0, 4.0):
        configs.append((f"+{layers} read s{sc}", {L: d[L] for L in layers}, "read", sc))
# negative direction (sign flip)
for layers in ([24,26],):
    for sc in (1.0, 2.0):
        configs.append((f"-{layers} read s{sc}", {L: -d[L] for L in layers}, "read", sc))
# prefix / context positions
for pos in ("prefix", "context"):
    for layers in ([24,26], [26,28,30]):
        for sc in (1.0, 2.0):
            configs.append((f"+{layers} {pos} s{sc}", {L: d[L] for L in layers}, pos, sc))

best = None
for name, vecs, pos, sc in configs:
    p, r = score(vecs, pos, sc)
    flag = " *" if p > baseline + 1e-9 else ""
    print(f"{name:26s} pass@10={p:.4f} rank={r:.3f}{flag}")
    if best is None or p > best[1]:
        best = (name, p, r, vecs, pos, sc)
print(f"\nBEST: {best[0]} pass@10={best[1]:.4f} rank={best[2]:.3f}")

